Object.assign(bank,{"pe_case": {"title": "Investment case", "topic": "Returns & downside", "en": "What would make a business an attractive buyout candidate, and what would cause you to reject the deal?", "guide": "Discuss cash generation, competitive position, capital needs, financing, and downside scenarios. Explain how the return depends on operating performance and exit assumptions.", "retry": "Choose one business and explain both the investment thesis and a specific reason to walk away."}, "vc_case": {"title": "Startup evaluation", "topic": "Market & unit economics", "en": "How would you evaluate an early-stage startup with fast revenue growth but negative cash flow?", "guide": "Separate market size, customer retention, unit economics, cash runway, and the path to sustainable growth. Explain what additional evidence you need.", "retry": "Identify a metric that would challenge your thesis, and show how you would investigate it."}, "portfolio": {"title": "Portfolio construction", "topic": "Allocation & risk", "en": "How would you decide whether to add a new investment to an existing portfolio?", "guide": "Consider the mandate, expected return, risk contribution, correlations, liquidity, constraints, and position size. State the assumptions behind your analysis.", "retry": "Explain how the same investment could fit one portfolio but not another."}, "credit_risk": {"title": "Risk assessment", "topic": "Exposure & stress testing", "en": "How would you assess the risk of a portfolio during a sudden market shock?", "guide": "Identify material exposures, examine liquidity and concentrations, and compare plausible stress scenarios. Explain the limitations of historical measures.", "retry": "Describe one concrete stress scenario and what action its results would inform."}, "forecast": {"title": "Financial planning", "topic": "Forecasting & business drivers", "en": "Revenue is below plan but cash flow is above plan. How would you investigate the difference?", "guide": "Reconcile earnings and cash flow. Examine collection timing, working capital, capital expenditure, and one-off items before revising the forecast.", "retry": "Separate timing effects from lasting changes and name the data you would request."}, "engineering": {"title": "Engineering discussion", "topic": "Reliability & systems", "en": "How would you design a service that receives market data and makes it available to downstream applications?", "guide": "Clarify volume, latency, ordering, data quality, failure handling, and consumer needs. Explain the tradeoffs in the design.", "retry": "Walk through a failure scenario and describe how you would detect and recover from it."}, "ml": {"title": "Model evaluation", "topic": "Data & validation", "en": "How would you validate a predictive model when observations arrive over time and the underlying patterns may change?", "guide": "Explain the split strategy, leakage prevention, baseline, metrics, and monitoring. Match the evaluation to how predictions will be used.", "retry": "Describe how an apparently strong offline result could fail after deployment."}, "general_technical": {"title": "Role-specific experience", "topic": "Methods & tradeoffs", "en": "Walk me through a technically challenging project relevant to this role. What approach did you choose, and why?", "guide": "State the problem, constraints, alternatives, your contribution, and the evidence you used to judge the result.", "retry": "Make one tradeoff explicit and explain what would change your decision."}});
const trackQuestions={"quant": ["quant", "python"], "banking": ["banking", "valuation"], "markets": ["markets", "risk"], "pe": ["pe_case", "valuation"], "vc": ["vc_case", "valuation"], "equity": ["valuation", "risk"], "asset": ["portfolio", "risk"], "hedge": ["risk", "portfolio"], "corporate": ["forecast", "banking"], "risk_management": ["credit_risk", "markets"], "quant_trading": ["quant", "risk"], "quant_dev": ["engineering", "python"], "data": ["ml", "quant"], "software": ["engineering", "general_technical"], "custom": ["general_technical", "leadership"]};
const trackLabels={"banking": "Investment Banking", "pe": "Private Equity", "vc": "Venture Capital", "equity": "Equity Research", "asset": "Asset Management", "hedge": "Hedge Funds", "corporate": "Corporate Finance / FP&A", "markets": "Sales & Trading", "risk_management": "Risk Management", "quant": "Quantitative Research", "quant_trading": "Quantitative Trading", "quant_dev": "Quantitative Development", "data": "Data Science / Machine Learning", "software": "Software Engineering / FinTech"};
let config={company:'',role:'',track:'',customTrack:'',format:'',customFormat:'',customSections:[],stage:'',duration:0,language:'en-US',jd:'',resume:'',interviewer:''};
let elapsedMs=0,lastClockAt=0;
let questions=[],index=0,answers=[],active=false,paused=false,finished=false,seconds=0,answerStart=0,timer=null,stream=null,micStream=null,recognition=null,listening=false,wantsListening=false,speaking=false,voice=true,currentFollowup=null,originalAnswer='',originalTime=0,followupCount=0,toastTimer=null,speechEpoch=0;
const isChinese=()=>config.language==='zh-CN';
const isConfigured=()=>Boolean(config.company.trim()&&config.role.trim()&&config.jd.trim()&&config.track&&(config.track!=='custom'||config.customTrack.trim())&&config.stage&&Number.isInteger(config.duration)&&config.duration>=5&&config.duration<=60&&config.format&&(config.format!=='custom'||(config.customFormat.trim()&&config.customSections.length)));
function notify(text){$('#toast').textContent=text;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,6500)}
function makeQuestions(){let technical=trackQuestions[config.track]||['general_technical','leadership'];let ids=config.format==='coding'?['intro','coding','closing']:config.format==='behavioral'?['intro','behavioral','leadership','closing']:config.format==='technical'?[...technical,'leadership','closing']:['intro','behavioral',...technical,'closing'];if(config.format==='custom'){ids=['intro'];for(const section of config.customSections){if(section==='technical')ids.push(...technical);if(section==='behavioral')ids.push('behavioral');if(section==='coding')ids.push('coding')}ids.push('closing')}if(config.stage==='Superday / final round'&&config.format==='full')ids[1]='leadership';questions=[...new Set(ids)].map(id=>({...bank[id],id}));const intro=questions.find(q=>q.id==='intro');if(intro&&config.company&&config.role){intro.en=`Walk me through your background and why you’re interested in the ${config.role} role at ${config.company}.`;intro.zh=`请介绍你的背景，以及你为什么对${config.company}的${config.role}岗位感兴趣。`}renderRoadmap()}
function showView(view){if(view==='studio'&&!isConfigured()){view='setup';notify('Add your company, role, and job description, then choose your track and interview stage.');}if(active&&view==='setup'){notify('Finish this session before changing the interview setup.');return}if(active&&view==='report'){notify('Your feedback will be available after the session.');return}['studio','setup','report'].forEach(v=>$('#'+v+'-view').hidden=v!==view);document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#breadcrumb').textContent={studio:'Interview studio',setup:'Interview setup',report:'Session feedback'}[view];if(view==='report')renderReport();window.scrollTo({top:0,behavior:'smooth'})}
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>showView(b.dataset.view));$('#settings').onclick=$('#edit-setup').onclick=()=>showView('setup');
function renderRoadmap(){const done=new Set(answers.map(a=>a.id));$('#roadmap').innerHTML=questions.map((q,i)=>`<li class="${done.has(q.id)?'done':i===index&&!finished?'current':''}"><span class="step-number">${done.has(q.id)?icon('check'):String(i+1).padStart(2,'0')}</span><div><h3>${escapeHTML(q.title)}</h3><p>${escapeHTML(q.topic)}</p></div></li>`).join('');$('#progress-label').textContent=`${done.size} of ${questions.length}`;$('#progress-bar').style.width=`${done.size/questions.length*100}%`;$('#question-counter').textContent=active?`Question ${index+1} of ${questions.length}${currentFollowup?' · Follow-up':''}`:`${questions.length} questions · ${isChinese()?'中文':'English'}`}
$('#setup-form').onsubmit=e=>{e.preventDefault();if(active)return;config={company:$('#company-input').value.trim(),role:$('#role-input').value.trim(),track:$('#track-input').value,customTrack:$('#track-input').value==='custom'?$('#custom-track-input').value.trim():'',format:$('#format-input').value,customFormat:$('#format-input').value==='custom'?$('#custom-format-input').value.trim():'',customSections:$('#format-input').value==='custom'?Array.from(document.querySelectorAll('[name="custom-section"]:checked'),el=>el.value):[],stage:$('#stage-input').value,duration:Number($('#duration-input').value==='custom'?$('#custom-duration-input').value:$('#duration-input').value),language:'en-US',jd:$('#jd-input').value.trim(),resume:$('#resume-input').value,interviewer:$('#interviewer-input').value};if(!isConfigured()){notify('Complete the required fields, including a name for a custom track. For a custom format, describe your interview and select at least one practice section.');return}resetSession();$('#duration-label').textContent=`${config.duration} minutes`;$('#track-label').textContent=config.track==='custom'?config.customTrack:trackLabels[config.track];$('#session-title').textContent=`${config.company} · ${config.role}`;$('.company-monogram').textContent=config.company.split(/\s+/).map(s=>s[0]).slice(0,2).join('').toUpperCase();$('#mode-label').textContent=`${{full:'Technical + Behavioral',behavioral:'Behavioral',technical:'Technical',coding:'Coding',custom:'Custom interview'}[config.format]} · ${config.stage}`;renderContext();showView('studio');notify('Your room is ready. Enable your camera, then join the voice interview.');};
async function toggleCamera(){if(stream){stream.getTracks().forEach(t=>t.stop());stream=null;$('#camera').srcObject=null;$('#camera-placeholder').hidden=false;$('#camera-toggle').classList.add('off');$('#camera-toggle').setAttribute('aria-label','Enable camera');return}if(!navigator.mediaDevices?.getUserMedia){notify('Camera preview needs a supported browser and HTTPS or localhost. You can still practice with text.');return}try{stream=await navigator.mediaDevices.getUserMedia({video:{width:{ideal:640},height:{ideal:480}},audio:false});$('#camera').srcObject=stream;$('#camera-placeholder').hidden=true;$('#camera-toggle').classList.remove('off');$('#camera-toggle').setAttribute('aria-label','Disable camera')}catch(e){notify('Camera unavailable or permission denied. Allow camera access in your browser, or continue without video.')}}
$('#enable-camera').onclick=$('#camera-toggle').onclick=toggleCamera;
const Recognition=window.SpeechRecognition||window.webkitSpeechRecognition;
function stopRecognition(){if(recognition){recognition.onend=null;recognition.onresult=null;recognition.onerror=null;recognition.stop();recognition=null}listening=false;updateMic()}
function updateMic(){const on=!!micStream&&wantsListening;$('#mic-toggle').classList.toggle('off',!on);$('#mic-toggle').setAttribute('aria-label',on?'Mute microphone':'Enable microphone');$('#mic-toggle').setAttribute('aria-pressed',String(on));$('#transcript-label').textContent=listening?'Listening · Your words appear here.':!Recognition?'Speech recognition unavailable. Type your answer below.':'Type here, or use the microphone to transcribe.'}
function startRecognition(){if(!Recognition||!wantsListening||!active||paused||speaking||listening)return;const r=new Recognition();recognition=r;r.lang=config.language;r.continuous=true;r.interimResults=true;let base=$('#answer').value.trim(),confirmed='';r.onstart=()=>{listening=true;updateMic()};r.onresult=e=>{let interim='';for(let i=e.resultIndex;i<e.results.length;i++){if(e.results[i].isFinal)confirmed+=e.results[i][0].transcript+' ';else interim+=e.results[i][0].transcript}$('#answer').value=[base,confirmed,interim].filter(Boolean).join(' ').trim();$('#answer-status').textContent='Live transcript · You can edit this before submitting.'};r.onerror=e=>{if(e.error==='not-allowed'||e.error==='service-not-allowed'||e.error==='audio-capture'){wantsListening=false;notify('Speech input could not start. Check microphone permissions, or type your answer.')}else if(e.error==='network'){wantsListening=false;notify('Speech transcription is unavailable right now. You can type your answer instead.')}updateMic()};r.onend=()=>{listening=false;recognition=null;updateMic();if(wantsListening&&active&&!paused&&!speaking)setTimeout(startRecognition,500)};try{r.start()}catch(e){recognition=null;notify('Microphone transcription could not start. Try again or type your answer.')}}
async function toggleMic(){if(wantsListening){wantsListening=false;stopRecognition();micStream?.getTracks().forEach(t=>t.stop());micStream=null;updateMic();return}if(!Recognition){notify('This browser does not support live transcription. Try Chrome, or type your answers here.');return}if(!navigator.mediaDevices?.getUserMedia){notify('Microphone access needs HTTPS or localhost. You can use the text answer box.');return}try{micStream=await navigator.mediaDevices.getUserMedia({audio:true,video:false});wantsListening=true;updateMic();if(active)startRecognition();else notify('Microphone ready. Transcription begins after the interviewer finishes speaking. Your browser may use its speech service.')}catch(e){notify('Microphone access was not allowed. You can still type and submit answers.')}}
$('#mic-toggle').onclick=toggleMic;
function cancelSpeech(){speechEpoch++;window.speechSynthesis?.cancel();speaking=false;$('#video-stage').classList.remove('speaking')}
function speak(text){cancelSpeech();stopRecognition();if(!voice||!window.speechSynthesis){setStatus();startRecognition();return}const epoch=speechEpoch;const u=new SpeechSynthesisUtterance(text);u.lang=config.language;u.rate=.95;const voices=window.speechSynthesis.getVoices();const preferred=voices.find(v=>v.lang===config.language&&/Samantha|Daniel|Google US English|Ting|Xiaoxiao/.test(v.name))||voices.find(v=>v.lang===config.language);if(preferred)u.voice=preferred;const end=()=>{if(epoch!==speechEpoch)return;speaking=false;$('#video-stage').classList.remove('speaking');setStatus();startRecognition()};u.onend=end;u.onerror=end;speaking=true;$('#video-stage').classList.add('speaking');$('#interviewer-state').textContent='Alex is asking a question…';window.speechSynthesis.speak(u)}
$('#voice-toggle').onclick=()=>{voice=!voice;$('#voice-toggle').classList.toggle('off',!voice);$('#voice-toggle').setAttribute('aria-pressed',String(!voice));$('#voice-toggle').setAttribute('aria-label',voice?'Mute interviewer voice':'Enable interviewer voice');if(!voice){cancelSpeech();setStatus();startRecognition()}};
function setStatus(){if(!active)return;$('#interviewer-state').textContent=paused?'Take a breath. We’ll be here.':speaking?'Alex is asking a question…':wantsListening?'I’m listening. Take your time.':'Your turn. Speak with the mic on, or type below.';$('#stage-status').textContent=paused?'Session paused':'Interview in progress'}
const timeText=n=>`${String(Math.floor(n/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`;
function syncClock(){if(!active)return;const now=performance.now();if(!paused)elapsedMs+=Math.max(0,now-lastClockAt);lastClockAt=now;seconds=Math.min(config.duration*60,Math.floor(elapsedMs/1000));$('#timer').textContent=timeText(Math.max(0,config.duration*60-seconds));}
function tickClock(){if(!active)return;syncClock();if(seconds>=config.duration*60){finishSession();notify('Time is up. Your current answer is included in the review.');}}
document.addEventListener('visibilitychange',()=>{if(!document.hidden)tickClock()});
function showQuestion(){const q=questions[index];$('#coding-workspace').hidden=q.id!=='coding';document.querySelector('.studio-layout').classList.toggle('coding-layout',q.id==='coding');$('#question-type').textContent=currentFollowup?'FOLLOW-UP · RULE-BASED DEMO':`QUESTION ${String(index+1).padStart(2,'0')} · ${q.title.toUpperCase()}`;const text=currentFollowup||(isChinese()?q.zh:q.en);$('#current-question').textContent=text;$('#question-help').textContent=currentFollowup?'Let’s go one level deeper. Your earlier answer has been kept.':'Think out loud. We’ll review your answers together after the session.';$('#answer').value='';$('#answer-status').textContent='Transcript is kept in this session until you start again or reload.';$('#next-question').innerHTML=`${index===questions.length-1?'Finish & review':'Submit answer'} ${icon('arrow')}`;answerStart=seconds;renderRoadmap();speak(text)}
function startSession(){if(!isConfigured()){showView('setup');notify('Complete your interview setup before starting.');return}if(finished)resetSession();active=true;$('#video-stage').classList.add('running');$('#start-interview').hidden=true;$('#active-controls').hidden=false;$('#answer-area').hidden=false;$('#replay-question').hidden=false;$('#edit-setup').disabled=true;elapsedMs=0;lastClockAt=performance.now();$('#timer').textContent=timeText(config.duration*60);timer=setInterval(tickClock,250);showQuestion();setStatus()}
$('#start-interview').onclick=startSession;
$('#replay-question').onclick=()=>{if(active&&!paused)speak(currentFollowup||(isChinese()?questions[index].zh:questions[index].en))};
$('#pause-interview').onclick=()=>{syncClock();if(seconds>=config.duration*60){finishSession();notify('Time is up. Your current answer is included in the review.');return}paused=!paused;lastClockAt=performance.now();$('#pause-interview').innerHTML=icon(paused?'play':'pause');$('#pause-interview').setAttribute('aria-label',paused?'Resume interview':'Pause interview');$('#next-question').disabled=paused;$('#answer').disabled=paused;$('#replay-question').disabled=paused;if(paused){cancelSpeech();stopRecognition();micStream?.getAudioTracks().forEach(t=>t.enabled=false)}else{micStream?.getAudioTracks().forEach(t=>t.enabled=true);startRecognition()}setStatus()};
function countWords(t){return (t.match(/[\u3400-\u9fff]|[\p{L}\p{N}]+(?:['’-][\p{L}\p{N}]+)*/gu)||[]).length}
function followupFor(text,q){if(q.id==='closing'||q.id==='coding')return null;const short=countWords(text)<(isChinese()?55:35);if(short)return isChinese()?'可以用一个具体例子展开说明，并解释你的思考过程吗？':'Could you make that more concrete with an example and walk me through your reasoning?';if(['intro','behavioral','leadership'].includes(q.id)&&!/[0-9%]|result|outcome|improv|learn|achiev|结果|提升|学到|完成/i.test(text))return isChinese()?'最终的结果是什么？你从这次经历中学到了什么？':'What was the outcome, and what did you learn from that experience?';return null}
function saveCurrent(){const text=$('#answer').value.trim();if(!text&&!originalAnswer&&!(questions[index]?.id==='coding'&&codeTouched))return;const q=questions[index];answers.push({id:q.id,title:q.title,question:isChinese()?q.zh:q.en,answer:originalAnswer||text,followup:currentFollowup,followupAnswer:currentFollowup?text:'',seconds:originalTime+seconds-answerStart,code:q.id==='coding'?$('#code-editor').value:null,language:q.id==='coding'?$('#code-language').value:null,tests:q.id==='coding'?codeResult:null,guide:q.guide,retry:q.retry});originalAnswer='';originalTime=0;currentFollowup=null;$('#answer').value=''}
$('#next-question').onclick=()=>{if(!active||paused)return;stopRecognition();const value=$('#answer').value.trim();if(!value&&!(questions[index].id==='coding'&&codeTouched)){notify(isChinese()?'请先回答问题，或者选择结束面试。':'Add an answer before continuing, or end the session to review what you have.');startRecognition();return}const followup=!currentFollowup?followupFor(value,questions[index]):null;if(followup){originalAnswer=value;originalTime=seconds-answerStart;currentFollowup=followup;followupCount++;showQuestion();return}saveCurrent();if(index===questions.length-1){finishSession();return}index++;showQuestion()};
$('#end-interview').onclick=()=>$('#end-dialog').showModal();$('#close-dialog').onclick=$('#keep-going').onclick=()=>$('#end-dialog').close();$('#confirm-end').onclick=()=>{$('#end-dialog').close();finishSession()};
function stopDevices(){stopRecognition();wantsListening=false;micStream?.getTracks().forEach(t=>t.stop());stream?.getTracks().forEach(t=>t.stop());micStream=null;stream=null;$('#camera').srcObject=null;$('#camera-placeholder').hidden=false;$('#camera-toggle').classList.add('off');$('#camera-toggle').setAttribute('aria-label','Enable camera');updateMic()}
function finishSession(){if(!active)return;syncClock();if($('#end-dialog').open)$('#end-dialog').close();stopCodeRunner();$('#coding-workspace').hidden=true;document.querySelector('.studio-layout').classList.remove('coding-layout');stopRecognition();saveCurrent();active=false;paused=false;finished=true;clearInterval(timer);cancelSpeech();stopDevices();$('#video-stage').classList.remove('running');$('#stage-status').textContent='Session complete';$('#interviewer-state').textContent='You showed up. That’s progress.';$('#start-interview').hidden=false;$('#start-interview').innerHTML=`Practice again ${icon('arrow')}`;$('#active-controls').hidden=true;$('#answer-area').hidden=true;$('#replay-question').hidden=true;$('#edit-setup').disabled=false;$('#current-question').textContent='Your session is complete. Take a moment to reflect.';$('#question-help').textContent='Your answers and practice guidance are ready in Session feedback.';renderRoadmap();showView('report')}
function resetSession(){resetCode();$('#coding-workspace').hidden=true;document.querySelector('.studio-layout').classList.remove('coding-layout');active=false;finished=false;paused=false;seconds=0;elapsedMs=0;lastClockAt=0;index=0;answers=[];currentFollowup=null;originalAnswer='';originalTime=0;followupCount=0;clearInterval(timer);cancelSpeech();stopDevices();$('#timer').textContent=timeText(config.duration*60);$('#stage-status').textContent='Ready when you are';$('#interviewer-state').textContent='Let’s make your next interview feel familiar.';$('#start-interview').hidden=false;$('#start-interview').innerHTML=`Start interview ${icon('arrow')}`;$('#active-controls').hidden=true;$('#answer-area').hidden=true;$('#replay-question').hidden=true;$('#replay-question').disabled=false;$('#pause-interview').innerHTML=icon('pause');$('#next-question').disabled=false;$('#answer').disabled=false;$('#edit-setup').disabled=false;$('#question-type').textContent='BEFORE WE BEGIN';$('#current-question').textContent='A safe place to practice. A serious step forward.';$('#question-help').textContent='Alex will ask one question at a time. Answer naturally, take your time, and get your feedback at the end.';makeQuestions()}
function reviewObservation(a){const words=countWords(a.answer+' '+a.followupAnswer);if(words<25)return `Your recorded answer contains ${words} words or Chinese characters. Check whether you stated your reasoning and gave a concrete example.`;return `Your recorded answer contains ${words} words or Chinese characters over ${timeText(a.seconds)}. Review it for a clear opening, supporting evidence, and a direct conclusion.`}
function renderReport(){const root=$('#report-content');$('#download-report').hidden=!finished;if(!finished){root.innerHTML=`<div class="empty-report">${icon('file')}<h2>Your next breakthrough starts with practice.</h2><p>Finish a session to see your answers and a guided review, all in one place.</p><button class="primary-button" id="back-to-studio">Go to interview studio ${icon('arrow')}</button></div>`;$('#back-to-studio').onclick=()=>showView('studio');return}root.innerHTML=`<div class="report-summary"><div><small>YOUR INTERVIEW</small><strong>${escapeHTML(config.company)}</strong><p>${escapeHTML(config.role)} · ${escapeHTML(config.stage)}</p><p>${escapeHTML(config.track==='custom'?config.customTrack:(trackLabels[config.track]||''))}</p>${config.format==='custom'?`<p>Custom format: ${escapeHTML(config.customFormat)}</p>`:''}</div><div><small>TIME PRACTICED</small><strong>${timeText(seconds)}</strong><p>${config.duration}-minute limit · Pauses excluded</p></div><div><small>QUESTIONS ANSWERED</small><strong>${answers.length}<span style="color:#afb5bd;font-size:18px"> / ${questions.length}</span></strong><p>${followupCount} rule-based follow-up${followupCount===1?'':'s'}</p></div></div><div class="report-banner">${icon('file')}<span><strong>Prototype review — not an AI assessment.</strong> Your transcript and timing are real session data. Coaching below is prewritten guidance for each question; no technical accuracy, hiring readiness, or delivery score has been calculated.</span></div>${answers.length?answers.map((a,i)=>`<article class="review-card"><div class="review-top"><span>QUESTION ${String(i+1).padStart(2,'0')} · ${escapeHTML(a.title.toUpperCase())}</span><span>${timeText(a.seconds)}</span></div><h3>${escapeHTML(a.question)}</h3><div class="saved-answer">${escapeHTML(a.answer||'No spoken or typed explanation captured.')}</div>${a.code?`<div class="review-code"><span>${escapeHTML(a.language)} · ${a.tests?`${a.tests.passed} / ${a.tests.total} visible tests passed`:'Not tested'}</span><pre><code>${escapeHTML(a.code)}</code></pre></div>`:''}${a.followup?`<h3 class="followup-heading">Follow-up: ${escapeHTML(a.followup)}</h3><div class="saved-answer">${escapeHTML(a.followupAnswer||'No follow-up answer captured.')}</div>`:''}<p class="recording-note">${escapeHTML(reviewObservation(a))}</p><div class="coaching"><div><h4>WHAT A STRONG ANSWER COVERS</h4><p>${escapeHTML(a.guide)}</p></div><div><h4>TRY THIS IN YOUR NEXT PRACTICE</h4><p>${escapeHTML(a.retry)}</p></div></div></article>`).join(''):'<div class="empty-report"><h2>No answers captured this time.</h2><p>Start a new session and speak or type your answers before submitting.</p></div>'}<div class="report-actions"><button class="primary-button" id="practice-again">Practice again ${icon('arrow')}</button></div>`;$('#practice-again').onclick=()=>{resetSession();showView('studio')}}
$('#download-report').onclick=()=>{if(!finished)return;let content=`INTERVIEWPILOT — SESSION REVIEW\n${config.company} · ${config.role}\n${config.stage} · ${timeText(seconds)}\nDuration limit: ${config.duration} minutes (pauses excluded)\nTrack: ${config.track==='custom'?config.customTrack:trackLabels[config.track]}\n${config.format==='custom'?`Custom format: ${config.customFormat}\nSections: ${config.customSections.join(', ')}\n`:''}\nPROTOTYPE: transcripts and timings are from your session. Coaching is prewritten, not AI-generated.\n\n`;answers.forEach((a,i)=>{content+=`${i+1}. ${a.question}\n\nYour answer: ${a.answer}\n${a.code?`\nCode (${a.language}):\n${a.code}\nTests: ${a.tests?`${a.tests.passed}/${a.tests.total} visible tests passed`:'Not tested'}\n`:''}${a.followup?`\nFollow-up: ${a.followup}\nAnswer: ${a.followupAnswer||'Not answered'}\n`:''}\n${reviewObservation(a)}\n\nAnswer framework: ${a.guide}\nNext practice: ${a.retry}\n\n`});const url=URL.createObjectURL(new Blob([content],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='InterviewPilot-session-review.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
$('#answer').addEventListener('focus',()=>{if(listening){stopRecognition();$('#transcript-label').textContent='Transcription paused for editing. Leave this field to resume.'}});$('#answer').addEventListener('blur',()=>{if(wantsListening&&active&&!paused&&!speaking)startRecognition()});
window.addEventListener('beforeunload',e=>{if(active){e.preventDefault();e.returnValue=''}});window.addEventListener('pagehide',()=>{cancelSpeech();stopDevices()});
function renderContext(){const bits=[['Interview track',config.track==='custom'?config.customTrack:(trackLabels[config.track]||'')],['Custom interview format',config.customFormat||''],['Job description',config.jd],['Resume highlights',config.resume],['Interviewer background',config.interviewer]].filter(([,text])=>text.trim());$('#context-summary').hidden=!bits.length;$('#context-summary').innerHTML=bits.length?`<details><summary>${bits.length} context source${bits.length===1?'':'s'} attached <span>Used as context when you join the live call</span></summary>${bits.map(([title,text])=>`<div><strong>${escapeHTML(title)}</strong><p>${escapeHTML(text)}</p></div>`).join('')}</details>`:''}
function stopCodeRunner(){if(codeWorker){codeWorker.terminate();codeWorker=null}clearTimeout(codeTimeout);$('#run-code').disabled=$('#code-language').value==='python';$('#run-code').innerHTML=icon('play')+' Run tests'}
function resetCode(){stopCodeRunner();$('#code-editor').value=starterCode[$('#code-language').value];codeTouched=false;codeResult=null;$('#test-results').textContent='Run your solution against 4 visible test cases. Explain your reasoning aloud as you code.'}
$('#code-editor').value=starterCode.javascript;
$('#code-editor').oninput=()=>{codeTouched=true;codeResult=null;stopCodeRunner();$('#test-results').textContent='Code changed. Run the tests again to check this version.'};
$('#code-editor').onkeydown=e=>{if(e.key==='Tab'){e.preventDefault();const t=e.currentTarget;const start=t.selectionStart,end=t.selectionEnd;t.setRangeText('  ',start,end,'end');t.dispatchEvent(new Event('input'))}};
$('#code-language').onchange=()=>{$('#code-runtime-note').textContent=$('#code-language').value==='python'?'Python practice editor · Execution not connected':'JavaScript runs locally · 2-second limit';resetCode()};
$('#reset-code').onclick=()=>{if(codeTouched&&!window.confirm('Reset your current solution? Your code will be replaced with the starter.'))return;resetCode()};
$('#run-code').onclick=()=>{if($('#code-language').value!=='javascript')return;stopCodeRunner();const source=$('#code-editor').value;codeTouched=true;codeResult=null;const cases=[{values:[2,7,11,15],target:9},{values:[3,2,4],target:6},{values:[3,3],target:6},{values:[-3,4,3,90],target:0}];const workerSource=`self.fetch=undefined;self.XMLHttpRequest=undefined;self.WebSocket=undefined;self.importScripts=undefined;\n${source}\nself.onmessage = function(event) { const results=event.data.map(c=>{try{const output=twoSum([...c.values],c.target);const passed=Array.isArray(output)&&output.length===2&&output.every(i=>Number.isInteger(i)&&i>=0&&i<c.values.length)&&output[0]!==output[1]&&c.values[output[0]]+c.values[output[1]]===c.target;return {passed,output:JSON.stringify(output)??'undefined'};}catch(e){return {passed:false,output:String(e.message)}}});self.postMessage(results); };`;const url=URL.createObjectURL(new Blob([workerSource],{type:'text/javascript'}));try{codeWorker=new Worker(url);URL.revokeObjectURL(url);$('#run-code').disabled=true;$('#run-code').textContent='Running…';$('#test-results').textContent='Running 4 test cases…';codeWorker.onmessage=e=>{const results=e.data;if(!Array.isArray(results)||results.length!==cases.length){$('#test-results').textContent='The runner received an invalid result.';stopCodeRunner();return}codeResult={passed:results.filter(r=>r.passed===true).length,total:cases.length};$('#test-results').innerHTML=`<strong>${codeResult.passed} / ${cases.length} visible tests passed</strong>`+results.map((r,i)=>`<div class="test-case"><span class="${r.passed?'test-pass':'test-fail'}">${r.passed?'PASS':'FAIL'}</span><code>[${cases[i].values.join(', ')}], target ${cases[i].target}</code><span>→ ${escapeHTML(String(r.output).slice(0,200))}</span></div>`).join('');stopCodeRunner()};codeWorker.onerror=e=>{e.preventDefault();$('#test-results').textContent='Could not run this solution: '+e.message;stopCodeRunner()};codeTimeout=setTimeout(()=>{$('#test-results').textContent='Time limit exceeded (2 seconds). Check for an infinite loop, then try again.';stopCodeRunner()},2000);codeWorker.postMessage(cases)}catch(e){URL.revokeObjectURL(url);$('#test-results').textContent='The code runner is unavailable in this browser. You can still save your solution for review.';stopCodeRunner()}};
$('#duration-input').onchange=()=>{const custom=$('#duration-input').value==='custom';$('#custom-duration-field').hidden=!custom;$('#custom-duration-input').required=custom;$('#custom-duration-input').disabled=!custom;};
$('#custom-duration-input').disabled=true;
$('#track-input').onchange=()=>{const custom=$('#track-input').value==='custom';$('#custom-track-field').hidden=!custom;$('#custom-track-input').required=custom;};
$('#format-input').onchange=()=>{const custom=$('#format-input').value==='custom';$('#custom-format').hidden=!custom;$('#custom-format-input').required=custom;};
makeQuestions();updateMic();$('#camera-toggle').classList.add('off');showView('setup');
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'read_interview_session',description:'Read the current interview phase, question, and progress without changing the session.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute(input){if(!input||Object.keys(input).length)throw new Error('Expected an empty object');return {phase:active?(paused?'paused':'active'):finished?'complete':'ready',company:config.company,role:config.role,stage:config.stage,question:active?$('#current-question').textContent:null,answered:answers.length,total:questions.length}}})).catch(()=>{})}catch{}}
